CORROBORATION = {
    ('seoyangsa', '나바리노 해전'): [dict(url='https://www.rmg.co.uk/collections/objects/rmgc-object-12114', title='Royal Museums Greenwich — 1827년 나바리노 해전')],
    ('seoyangsa', '드레드 스콧 판결'): [dict(url='https://www.archives.gov/milestone-documents/dred-scott-v-sandford', title='미국 국립문서기록관리청 — 1857년 판결 원문')],
    ('seoyangsa', '전미여성기구'): [dict(url='https://now.org/faq/when-and-how-was-now-founded/', title='전미여성기구 — 공식 창립 연혁')],
    ('dongyangsa', '등록법'): [dict(url='https://www.zjskw.gov.cn/art/2023/6/11/art_1229501970_52717.html', title='저장성 사회과학연합회 — 송대 과거의 답안 전사 제도')],
    ('dongyangsa', '농상집요'): [dict(url='https://encykorea.aks.ac.kr/Article/E0080261', title='한국민족문화대백과사전 — 원조정본농상집요')],
}

def render():
    for subject, block in SEEDS.items():
        notes = {n['id']: n for n in json.loads((ROOT/f'public/data/subjects/{subject}/notes.json').read_text())}
        rows = []
        for index, line in enumerate(block.strip().splitlines(), 1):
            fields = line.split('|')
            if len(fields) != 6:
                raise ValueError((subject, index, 'expected six authored fields', len(fields)))
            number, answer, prompt, selected, explain, spellings = fields
            page = f'{subject}-textbook-page-{number}'
            quotes = selected.replace('\\n', '\n').split('§')
            for quote in quotes:
                if quote not in notes[page]['text']:
                    raise ValueError((subject, index, page, 'nonverbatim selection', quote))
            aliases = [a for a in spellings.split(';') if a]
            # Spaces and NFC are handled by the grader, so do not duplicate them.
            import re, unicodedata
            norm = lambda a: re.sub(r'\s+', '', unicodedata.normalize('NFC', a))
            seen = {norm(answer)}
            aliases = [a for a in aliases if not (norm(a) in seen or seen.add(norm(a)))]
            rows.append(dict(id=f'{subject}-page-practice-review{BATCH}-{index:03}',
                page=page, kind='short', prompt=prompt, answer=answer,
                acceptedAnswers=aliases, evidence=[dict(page=page, quote=q) for q in quotes],
                explain=explain, topic=answer))
        for row in rows:
            links = CORROBORATION.get((subject, row['answer']))
            if links:
                row['corroboration'] = links
        document = dict(schemaVersion=1, subject=subject, batch=BATCH,
            review='AI-authored; exact selected transcription checked; no claim of fresh scan or expert verification', questions=rows)
        path = ROOT/f'tools/history-questions/page-supplements/{subject}.json'
        path.write_text(json.dumps(document, ensure_ascii=False, indent=2)+'\n')
        print(subject, len(rows))

if __name__ == '__main__':
    render()
